fn ttl_days(ttl_msec: i64) -> Value {
    if ttl_msec % 86_400_000 == 0 {
        Value::from(ttl_msec / 86_400_000)
    } else {
        Value::from(ttl_msec as f64 / 86_400_000.0)
    }
}

